program='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]
    marks = [(r, c, g[r][c]) for r in range(h) for c in range(w)
             if g[r][c] != background and 0 < r < h-1 and 0 < c < w-1]
    if not marks:
        return g
    fill = Counter(v for _, _, v in marks).most_common(1)[0][0]

    def runs(line):
        out = []
        i = 0
        while i < len(line):
            color = line[i]
            if color == background:
                i += 1
                continue
            a = i
            while i+1 < len(line) and line[i+1] == color:
                i += 1
            b = i
            if b > a:
                out.append((a, b, color))
            i += 1
        return out

    # Pair matching bars on opposite edges. The marked coordinates within one
    # bar are copied by offset to the opposing bar, and both project inward.
    candidates = []
    for first, last, axis in ((0, h-1, 'horizontal'), (0, w-1, 'vertical')):
        if axis == 'horizontal':
            r1, r2 = runs(g[first]), runs(g[last])
            for a, b, color in r1:
                for d, e, color2 in r2:
                    if color == color2:
                        contained = [(r,c,v) for r,c,v in marks if a <= c <= b]
                        if contained:
                            candidates.append((len(contained), axis, (a,b,color), (d,e,color2), contained, first, last))
                        contained2 = [(r,c,v) for r,c,v in marks if d <= c <= e]
                        if contained2:
                            candidates.append((len(contained2), axis, (d,e,color2), (a,b,color), contained2, last, first))
        else:
            r1 = runs([g[r][first] for r in range(h)])
            r2 = runs([g[r][last] for r in range(h)])
            for a, b, color in r1:
                for d, e, color2 in r2:
                    if color == color2:
                        contained = [(r,c,v) for r,c,v in marks if a <= r <= b]
                        if contained:
                            candidates.append((len(contained), axis, (a,b,color), (d,e,color2), contained, first, last))
                        contained2 = [(r,c,v) for r,c,v in marks if d <= r <= e]
                        if contained2:
                            candidates.append((len(contained2), axis, (d,e,color2), (a,b,color), contained2, last, first))
    if not candidates:
        return g
    _, axis, src, dst, contained, src_edge, dst_edge = max(candidates, key=lambda x: x[0])
    a, b, _ = src
    d, e, _ = dst
    for r, c, _ in contained:
        coordinate = c if axis == 'horizontal' else r
        offset = coordinate - a
        mapped = d + offset
        if not d <= mapped <= e:
            continue
        if axis == 'horizontal':
            if src_edge == 0:
                for rr in range(1, r):
                    if g[rr][c] == background: g[rr][c] = fill
            else:
                for rr in range(h-2, r, -1):
                    if g[rr][c] == background: g[rr][c] = fill
            g[r][c] = 4
            if dst_edge == 0:
                for rr in range(1, h):
                    if g[rr][mapped] == background: g[rr][mapped] = fill
            else:
                for rr in range(h-2, -1, -1):
                    if g[rr][mapped] == background: g[rr][mapped] = fill
        else:
            if src_edge == 0:
                for cc in range(1, c):
                    if g[r][cc] == background: g[r][cc] = fill
            else:
                for cc in range(w-2, c, -1):
                    if g[r][cc] == background: g[r][cc] = fill
            g[r][c] = 4
            if dst_edge == 0:
                for cc in range(1, w):
                    if g[mapped][cc] == background: g[mapped][cc] = fill
            else:
                for cc in range(w-2, -1, -1):
                    if g[mapped][cc] == background: g[mapped][cc] = fill
    return g
'''
